          "Do forms, calls, bookings, and checkout events work on priority devices?",
          "Are duplicate events inflating the denominator or outcome?",
          "Does cross-domain or third-party form behavior preserve the intended attribution?",
          "Are CRM source fields and qualification stages populated consistently?",
          "Did spam filtering or lead-routing rules change?",
